file_path: hooks/block-rm.sh
content:
#!/bin/sh
# PreToolUse guard: block any `rm` that is recursive and force (rm -rf and its
# spellings). Reads the hook event JSON on stdin; exit 2 blocks, stderr is the reason.
script=$(cat <<'PY'
import json
import re
import shlex
import sys


def is_rm_recursive_force(command):
    # Split on shell operators so each simple command is checked on its own.
    for segment in re.split(r'[;&|\n(){}`]', command):
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        for i, token in enumerate(tokens):
            # Match /bin/rm, \rm and "rm" alike; quoted text like "rm -rf" is one token and does not match.
            if token.lstrip('\\').rsplit('/', 1)[-1] != 'rm':
                continue
            recursive = force = False
            # GNU rm accepts options after operands, so scan every following argument.
            for arg in tokens[i + 1:]:
                if arg == '--':
                    break
                if arg.startswith('--'):
                    recursive |= arg == '--recursive'
                    force |= arg == '--force'
                elif arg.startswith('-') and len(arg) > 1:
                    recursive |= any(c in 'rR' for c in arg[1:])
                    force |= 'f' in arg[1:]
            if recursive and force:
                return True
    return False


event = json.load(sys.stdin)
command = (event.get('tool_input') or {}).get('command') or ''
if is_rm_recursive_force(command):
    sys.stderr.write(
        'Blocked: recursive forced deletion (rm -rf) is not allowed in this project. '
        'Delete specific files by name, or ask the user to run the command themselves.\n'
    )
    sys.exit(2)
sys.exit(0)
PY
)
exec python3 -I -c "$script"

